// Classifies std::stoi behaviour WITHOUT aborting, so we can enumerate cases.
// Mirrors test11.cpp's arg handling exactly.
#include <iostream>
#include <string>
#include <stdexcept>
int main(int argc, char* argv[]) {
    int count = 11;
    if (argc > 1 && std::string(argv[1]) == "--a") {
        try {
            count = std::stoi(argv[2]);
        } catch (const std::out_of_range& e) {
            std::cout << "OUT_OF_RANGE what=" << e.what() << std::endl; return 2;
        } catch (const std::invalid_argument& e) {
            std::cout << "INVALID_ARGUMENT what=" << e.what() << std::endl; return 3;
        } catch (const std::logic_error& e) {
            std::cout << "LOGIC_ERROR what=" << e.what() << std::endl; return 4;
        }
    }
    std::cout << "OK " << count << std::endl;
    return 0;
}
EOF
g++ -O2 -o oracle oracle.cpp && g++ -O2 -o stoiprobe2 stoiprobe.cpp && echo "built"
