// Independent Rust reimplementation of test11's argv dispatch + std::stoi(base 10).
// Prints "OK <n>" | "THROW LOGIC_ERROR" | "THROW INVALID_ARGUMENT" | "THROW OUT_OF_RANGE"
use std::os::unix::ffi::OsStrExt;

fn is_c_space(b: u8) -> bool { matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') }

/// strtol(str, NULL, 10) + libstdc++ stoi range check. Err(true)=out_of_range, Err(false)=invalid
fn stoi(s: &[u8]) -> Result<i32, bool> {
    let mut i = 0usize;
    while i < s.len() && is_c_space(s[i]) { i += 1; }
    let mut neg = false;
    if i < s.len() && (s[i] == b'+' || s[i] == b'-') { neg = s[i] == b'-'; i += 1; }
    let start = i;
    // accumulate in i128 with saturation to detect long-overflow (ERANGE) like strtol
    let mut acc: i128 = 0;
    let mut saturated = false;
    while i < s.len() && s[i].is_ascii_digit() {
        if !saturated {
            acc = acc * 10 + (s[i] - b'0') as i128;
            if acc > (1i128 << 100) { saturated = true; }
        }
        i += 1;
    }
    if i == start { return Err(false); }              // no digits -> invalid_argument
    let v: i128 = if neg { -acc } else { acc };
    if saturated || v > i64::MAX as i128 || v < i64::MIN as i128 { return Err(true); } // strtol ERANGE
    if v > i32::MAX as i128 || v < i32::MIN as i128 { return Err(true); }              // stoi range
    Ok(v as i32)
}

fn main() {
    let argv: Vec<Vec<u8>> = std::env::args_os().map(|a| a.as_bytes().to_vec()).collect();
    let argc = argv.len();
    let mut count: i32 = 11;
    if argc > 1 && argv[1] == b"--a" {
        if argc < 3 { println!("THROW LOGIC_ERROR"); return; }   // std::string(nullptr)
        match stoi(&argv[2]) {
            Ok(v) => count = v,
            Err(true)  => { println!("THROW OUT_OF_RANGE"); return; }
            Err(false) => { println!("THROW INVALID_ARGUMENT"); return; }
        }
    }
    println!("OK {}", count);
}
EOF
