#include <stdio.h>
#include <stdlib.h>
#include <sys/wait.h>
#include <unistd.h>
int main(int argc, char** argv){
  pid_t p = fork();
  if(p==0){ execv(argv[1], &argv[1]); _exit(127); }
  int st; waitpid(p,&st,0);
  if(WIFEXITED(st)) printf("WIFEXITED status=%d\n", WEXITSTATUS(st));
  if(WIFSIGNALED(st)) printf("WIFSIGNALED signal=%d (%s) coredump=%d\n",
      WTERMSIG(st), WTERMSIG(st)==6?"SIGABRT":"other", WCOREDUMP(st));
  return 0;
}
EOF
